import resolved from '@/tokens/resolved.json';

// Token values for places Tailwind classes can't reach (metadata, the styleguide).
// Generated by scripts/build-tokens.mjs; never hard-code a hex value instead.

export type ColorToken = (typeof resolved.colors)[number];
export type TypeToken = (typeof resolved.types)[number];

export const colors: readonly ColorToken[] = resolved.colors;
export const types: readonly TypeToken[] = resolved.types;
export const families = resolved.families;
export const spacing = resolved.spacing;
export const radii = resolved.radii;
export const containers = resolved.containers;

export function color(name: string): string {
  const token = colors.find((c) => c.name === name);
  if (!token) throw new Error(`Unknown colour token: ${name}`);
  return token.value;
}
